/* ===== VENDOR DASHBOARD ===== */
const vb=()=>biz(ownerId());
const series=(seed,n,base,spread)=>Array.from({length:n},(_,i)=>Math.round(base+spread*Math.abs(Math.sin((i+1)*(seed.charCodeAt(1)||3)*1.7))));
const barChart=(vals,labels,fmt)=>{const m=Math.max(...vals,1);return `<div class="bars" role="img" aria-label="${t('Bar chart')}">${vals.map((v,i)=>`<i style="height:${Math.max(4,v/m*100)}%" title="${labels[i]}: ${fmt?fmt(v):v}"></i>`).join('')}</div><div class="row between xs muted" style="margin-top:4px">${labels.map(l=>`<span>${l}</span>`).join('')}</div>`};
const spark=(vals,color='var(--primary)')=>{const m=Math.max(...vals),n=Math.min(...vals),w=120,h=34,pts=vals.map((v,i)=>`${i*w/(vals.length-1)},${h-(v-n)/(m-n||1)*(h-4)-2}`).join(' ');return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/></svg>`};
const donut=(parts)=>{const tot=parts.reduce((a,p)=>a+p[1],0)||1;let a0=0;const R=40,C=2*Math.PI*R;return `<svg width="120" height="120" viewBox="0 0 120 120" role="img" aria-label="${t('Donut chart')}"><g transform="rotate(-90 60 60)">${parts.map(p=>{const len=p[1]/tot*C,el=`<circle cx="60" cy="60" r="${R}" fill="none" stroke="${p[2]}" stroke-width="18" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-a0}"/>`;a0+=len;return el}).join('')}</g><text x="60" y="66" text-anchor="middle" font-size="18" font-weight="700" fill="currentColor">${tot}</text></svg>`};
const lastDays=n=>Array.from({length:n},(_,i)=>new Date(Date.now()-(n-1-i)*DAY).toLocaleDateString('en-IN',{...IST,weekday:'short'}).slice(0,3));
const vOrders=()=>D().orders.filter(o=>o.bid===ownerId());
V.vhome=()=>{const b=vb();if(b.status==='pending'&&false)return '';const os=vOrders(),today=os.filter(o=>Date.now()-o.ts<DAY&&o.status!=='cancelled'),rev=today.reduce((a,o)=>a+o.subtotal-o.discount,0);const lows=D().products.filter(p=>p.bid===b.id&&p.stock<=p.low);const newO=os.filter(o=>o.status==='placed'),needReply=D().reviews.filter(r=>r.tid===b.id&&!r.reply&&r.status==='published');
 return `<div class="stack-lg">${gateNote(MYROLE())}<div class="row between wrap-r"><div><h1>${t('Namaste')}, ${esc(nm(b.name))}</h1><div class="small muted">${fdate(Date.now())}</div></div><div class="row">${apBadge(b.status)}<a class="btn g sm" href="#biz-${b.id}">${ic('eye',16)} ${t('View public page')}</a></div></div>
 ${newO.length&&canAct(MYROLE())?`<a class="alert warn" href="#${RT('vorders')}" style="animation:pulse 1.6s infinite">${ic('bell',20)}<div><b>${newO.length} ${t('new order(s) waiting')}</b> · ${t('Tap to accept')}</div></a>`:''}
 <div class="grid g3" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${kpi("Today’s orders",today.length,'12% '+t('vs yesterday'))}${kpi('Revenue today',inr(rev),'8%')}${kpi('Profile views',series(b.id,1,310,90)[0],'5%')}${kpi('QR scans',series(b.id,1,42,20)[0],'2%',false)}${kpi('Enquiries',9,'3')}${kpi('New reviews',D().reviews.filter(r=>r.tid===b.id&&Date.now()-r.ts<7*DAY).length,'')}</div>
 <div class="cols2 eq"><div class="card pad stack"><h3>${t('Revenue, last 7 days')}</h3>${barChart(series(b.id,7,1800,2600),lastDays(7),inr)}</div><div class="card pad stack"><h3>${t('Orders by status')}</h3><div class="row">${donut([['a',os.filter(o=>grp(o)==='active').length,'var(--primary)'],['b',os.filter(o=>grp(o)==='done').length,'var(--success)'],['c',os.filter(o=>grp(o)==='cancel').length,'var(--error)']])}<div class="stack small"><span><i style="color:var(--primary)">●</i> ${t('Active')}</span><span><i style="color:var(--success)">●</i> ${t('Completed')}</span><span><i style="color:var(--error)">●</i> ${t('Cancelled')}</span></div></div><div class="row between"><span class="small muted">${t('Profile views trend')}</span>${spark(series(b.id,10,200,160))}</div></div></div>
 <div class="cols2 eq"><div class="card pad stack"><h3>${t('Pending actions')}</h3>${[[newO.length,'New orders to accept','vorders'],[os.filter(o=>o.status==='ready'&&o.mode==='delivery'&&!o.riderId).length,'Orders waiting for a rider','vorders'],[needReply.length,'Reviews to reply','vreviews'],[D().offers.filter(o=>o.bid===b.id&&o.status==='pending').length,'Offers awaiting admin approval','voffers']].map(([n,l,r])=>`<a class="row between" href="#${r}" style="min-height:44px"><span>${t(l)}</span><span class="cnt" style="${n?'':'background:var(--surface-2);color:var(--muted)'}">${n}</span></a>`).join('')}</div>
 <div class="card pad stack"><h3>${t('Low-stock alerts')}</h3>${lows.length?lows.map(p=>`<div class="row between"><span>${p.emoji} ${esc(nm(p.name))}</span><span class="badge ${p.stock?'warn':'bad'}">${p.stock?p.stock+' '+t('left'):t('Out of stock')}</span></div>`).join('')+`<a class="btn o sm" href="#vinv">${t('Update stock')}</a>`:`<span class="small muted">${t('All items are well stocked.')}</span>`}</div></div></div>`};
/* orders */
const VTABS=[['new','New',o=>o.status==='placed'],['prog','In progress',o=>['accepted','preparing'].includes(o.status)],['ready','Ready / out',o=>['ready','out'].includes(o.status)],['done','Completed',o=>['delivered','pickedup'].includes(o.status)],['cancel','Cancelled',o=>['cancelled','refunded'].includes(o.status)]];
V.vorders=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const tab=UI.vtab||'new',f=VTABS.find(x=>x[0]===tab)[2],all=vOrders(),l=all.filter(f);
 return `<div class="stack"><h1>${t('Orders')}</h1><div class="tabs" role="tablist">${VTABS.map(([k,lb,fn])=>`<button role="tab" class="${tab===k?'on':''}" data-act="vtab" data-v="${k}">${t(lb)} <span class="cnt" style="${k==='new'&&all.filter(fn).length?'':'background:var(--surface-2);color:var(--text)'}">${all.filter(fn).length}</span></button>`).join('')}</div>${tbl(['Order','Customer','Items','Total','Mode','Status',''],l.map(o=>[`<b>${o.id}</b><div class="xs muted">${ago(o.ts)}</div>`,esc(o.cust),o.items.length,inr(orderTotal(o)),o.mode==='pickup'?t('Pickup'):t('Delivery'),stBadge(o.status,o),`<a class="btn p sm" href="#${RT('vorder')}-${o.id}">${t('Open')}</a>`]))}</div>`};
A.vtab=el=>{UI.vtab=el.dataset.v;render(true)};
V.vorder=id=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const o=order(id);if(!o||o.bid!==ownerId())return V.nf();const b=vb(),job=D().jobs.find(j=>j.oid===id),rd=o.riderId?rider(o.riderId):null,self=b.del.mode==='self';
 let acts='';const A_=(a,l,c='p')=>`<button class="btn ${c} block" data-act="${a}" data-id="${id}">${l}</button>`;
 if(o.status==='placed')acts=`<div class="grid g2">${A_('vaccept',t('Accept order'))}${A_('vreject',t('Reject'),'d')}</div>`;
 else if(o.status==='accepted')acts=o.mode==='pickup'?A_('vready',t('Mark ready for pickup')):A_('vprep',t('Start preparing'));
 else if(o.status==='preparing')acts=A_('vready',t('Mark ready'));
 else if(o.status==='ready'&&o.mode==='pickup')acts=A_('vpicked',t('Handed to customer (enter code)'));
 else if(o.status==='ready'&&o.mode==='delivery')acts=self?A_('vout',t('Out for delivery (my delivery boy)')):(job?alertBox('info',job.riderId?`${t('Rider')} <b>${esc(rider(job.riderId).name)}</b> ${t('is on the way to the shop')}`:t('Waiting for a rider to accept…'),'bike')+(job.riderId?'':`<div class="grid g2"><button class="btn o" data-act="assignRider" data-id="${id}">${t('Assign rider')}</button><button class="btn g" data-act="requestRider" data-id="${id}">${t('Re-send request')}</button></div>`):A_('requestRider',t('Request ApnaTown rider')));
 else if(o.status==='out'&&self)acts=A_('vdeliv',t('Delivered (enter customer OTP)'));
 else if(o.status==='out')acts=alertBox('info',`${t('Out for delivery with')} ${rd?esc(rd.name):t('rider')}`,'bike');
 return `<div class="stack-lg"><a class="btn t sm" href="#${RT('vorders')}" style="justify-self:start">${ic('cl',16)} ${t('All orders')}</a><div class="row between wrap-r"><div><h1>${o.id}</h1><div class="small muted">${fdt(o.ts)}</div></div>${stBadge(o.status,o)}</div>
 ${o.refund&&o.refund.status==='requested'?alertBox('warn',`<b>${t('Refund requested')}</b>: ${esc(o.refund.reason||o.cancel&&o.cancel.reason||'')}<div class="row" style="margin-top:8px"><button class="btn p sm" data-act="vrefund" data-id="${id}" data-v="approve">${t('Approve refund')}</button><button class="btn g sm" data-act="vrefund" data-id="${id}" data-v="decline">${t('Decline')}</button></div>`):''}
 <div class="cols2"><div class="stack"><div class="card pad stack"><h3>${t('Items')}</h3>${o.items.map(i=>`<div class="row between"><span>${i.emoji} ${esc(nm(i.name))} ${i.variant?'('+esc(i.variant)+')':''} × ${i.qty}</span><b>${inr(i.price*i.qty)}</b></div>`).join('')}<div class="divider"></div><dl class="kv"><dt>${t('Subtotal')}</dt><dd>${inr(o.subtotal)}</dd><dt>${t('Delivery')}</dt><dd>${inr(o.delivery)}</dd><dt>${t('Payment')}</dt><dd>${esc(o.pay.method)} · ${o.pay.status}</dd><dt><b>${t('Total')}</b></dt><dd><b>${inr(orderTotal(o))}</b></dd></dl>${o.partial?alertBox('warn',esc(o.partial)):''}</div>
 <div class="card pad stack"><h3>${t('Customer')}</h3><dl class="kv"><dt>${t('Name')}</dt><dd>${esc(o.cust)}</dd><dt>${t('Phone')}</dt><dd><a href="${telH(o.phone)}">+91 ${esc(o.phone)}</a></dd><dt>${o.mode==='pickup'?t('Pickup'):t('Deliver to')}</dt><dd>${esc(o.addr||t('Customer will collect'))}</dd></dl></div></div>
 <div class="stack"><div class="card pad stack"><h3>${t('Update status')}</h3>${acts||`<span class="muted small">${t('No further action needed.')}</span>`}${['placed','accepted','preparing'].includes(o.status)?`<button class="btn g" data-act="unavail" data-id="${id}">${t('Mark an item unavailable')}</button>`:''}<button class="btn g" data-act="slip" data-id="${id}">${ic('print',16)} ${t('Print order slip')}</button></div><div class="card pad"><h3 style="margin-bottom:8px">${t('Timeline')}</h3>${timeline(o)}</div></div></div></div>`};
A.vaccept=el=>{const o=order(el.dataset.id);setStatus(o,'accepted');render(true);toast(t('Order accepted'))};
A.vreject=el=>sheet(`<h3>${t('Reject this order?')}</h3><form data-form="vreject" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('Reason','reason','',{type:'select',opts:[['Item out of stock','Item out of stock'],['Shop is closing','Shop is closing'],['Too far to deliver','Too far to deliver'],['Other','Other']]})}<button class="btn d">${t('Reject order')}</button></form>`);
F.vreject=d=>{const o=order(d.id);o.cancel={by:'vendor',reason:d.reason};if(o.pay.status==='paid')o.refund={status:'requested',steps:[['requested',Date.now()]]};setStatus(o,'cancelled');notify('admin','Vendor cancelled '+o.id,d.reason,'aorder-'+o.id,'order');save();closeSheet();render(true);toast(t('Order rejected'))};
A.vprep=el=>{setStatus(order(el.dataset.id),'preparing');render(true)};
A.vready=el=>{const o=order(el.dataset.id);setStatus(o,'ready');if(o.mode==='delivery'&&vb().del.mode==='rider')A.requestRider({dataset:{id:o.id}},true);render(true);toast(t('Marked ready'))};
A.requestRider=(el,quiet)=>{const o=order(el.dataset.id),b=biz(o.bid);let j=D().jobs.find(x=>x.oid===o.id);const d=o.addrPos?km(b,o.addrPos):2.5;if(!j){D().jobs.unshift({id:rid('J'),oid:o.id,riderId:null,status:'requested',ts:Date.now(),dist:Math.round(d*10)/10,earn:riderEarn(d),expires:Date.now()+3600000})}else{j.ts=Date.now()}notify('rider','New delivery nearby',nm(b.name)+' · earn '+inr(riderEarn(d)),'rreq','job');save();if(!quiet){render(true);toast(t('Rider request sent'),'bike')}};
A.assignRider=el=>{const o=order(el.dataset.id);sheet(`<h3>${t('Assign a rider')}</h3><div class="stack" style="margin-top:10px">${D().riders.filter(r=>r.status==='approved').map(r=>`<button class="card pad row" style="text-align:left" data-act="doAssign" data-id="${o.id}" data-r="${r.id}"><div class="mini art" style="--h:30;width:44px;height:44px">🛵</div><span class="grow"><b>${esc(r.name)}</b><span class="small t2" style="display:block">${stars(r.rating)} ${r.rating} · ${esc(r.area)}</span></span><span class="badge ${r.online?'ok':'neu'}">${r.online?t('Online'):t('Offline')}</span></button>`).join('')}</div>`)};
A.doAssign=el=>{const o=order(el.dataset.id),r=rider(el.dataset.r);let j=D().jobs.find(x=>x.oid===o.id);if(!j){A.requestRider({dataset:{id:o.id}},true);j=D().jobs.find(x=>x.oid===o.id)}j.riderId=r.id;j.status='accepted';o.riderId=r.id;notify('rider','Delivery assigned to you',o.id,'ractive','job');save();closeSheet();render(true);toast(t('Rider assigned'),'bike')};
A.vout=el=>{setStatus(order(el.dataset.id),'out');render(true)};
const otpAsk=(title,act,id,label)=>sheet(`<h3>${title}</h3><form data-form="otpcheck" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${id}"><input type="hidden" name="act" value="${act}">${field(label,'code','',{req:1,im:'numeric',pattern:'[0-9]{4}',hint:'4 digits'})}<button class="btn p">${t('Confirm')}</button></form>`);
A.vdeliv=el=>otpAsk(t('Delivery OTP'),'deliv',el.dataset.id,'Customer OTP');A.vpicked=el=>otpAsk(t('Pickup code'),'pick',el.dataset.id,'Customer pickup code');
F.otpcheck=d=>{const o=order(d.id);const ok=d.act==='deliv'?d.code===o.otp:d.code===o.pickupCode;if(!ok){toast(t('Wrong code. Please check with the customer.'),'alert');return}setStatus(o,d.act==='deliv'?'delivered':'pickedup');if(o.pay.status==='pending')o.pay.status='paid';closeSheet();render(true);toast(t('Order completed'),'check')};
A.slip=el=>{const o=order(el.dataset.id);sheet(`<div id="slip"><h3>${esc(nm(biz(o.bid).name))}</h3><div class="small">${t('Order')} ${o.id} · ${fdt(o.ts)}</div><div class="divider"></div>${o.items.map(i=>`<div class="row between"><span>${esc(nm(i.name))} × ${i.qty}</span><span>${inr(i.price*i.qty)}</span></div>`).join('')}<div class="divider"></div><div class="row between"><b>${t('Total')}</b><b>${inr(orderTotal(o))}</b></div><div class="small">${esc(o.cust)} · ${esc(o.phone)}<br>${esc(o.addr||t('Pickup'))}</div></div><button class="btn p block noprint" style="margin-top:12px" onclick="window.print()">${ic('print',16)} ${t('Print')}</button>`)};
A.unavail=el=>{const o=order(el.dataset.id);sheet(`<h3>${t('Item unavailable')}</h3><form data-form="unavail" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${o.id}">${o.items.map((i,k)=>`<label class="check card pad"><input type="checkbox" name="i${k}" style="accent-color:var(--primary)"> ${esc(nm(i.name))} × ${i.qty}</label>`).join('')}<div class="small muted">${t('The customer will be told and the bill updated. Pre-paid amount is refunded for these items.')}</div><button class="btn p">${t('Remove selected items')}</button></form>`)};
F.unavail=d=>{const o=order(d.id),rm=o.items.filter((_,k)=>d['i'+k]);if(!rm.length){closeSheet();return}if(rm.length===o.items.length){closeSheet();F.vreject({id:o.id,reason:'Item out of stock'});return}o.items=o.items.filter((_,k)=>!d['i'+k]);o.subtotal=o.items.reduce((a,i)=>a+i.price*i.qty,0);o.partial='Removed: '+rm.map(i=>nm(i.name)).join(', ')+' (out of stock)';notify('cust','Order '+o.id+' updated',o.partial,'order-'+o.id,'order');save();closeSheet();render(true);toast(t('Customer notified'))};
A.vrefund=el=>{const o=order(el.dataset.id),ap=el.dataset.v==='approve';if(ap){o.refund.steps.push(['approved',Date.now()]);o.refund.status='approved';o.case&&(o.case.notes.push('Vendor approved refund'));notify('cust','Refund approved',o.id,'order-'+o.id,'order')}else{o.refund.status='declined';o.case&&o.case.notes.push('Vendor declined; escalated to admin');notify('admin','Refund declined by vendor',o.id,'aorder-'+o.id,'order')}save();render(true);toast(ap?t('Refund approved'):t('Escalated to admin'))};
/* products */
V.vproducts=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const b=vb(),q=(UI.vq||'').toLowerCase(),sel=UI.vsel||[];let l=D().products.filter(p=>p.bid===b.id&&(!q||nm(p.name).toLowerCase().includes(q)||p.sku.toLowerCase().includes(q)));if(UI.vfl==='low')l=l.filter(p=>p.stock<=p.low);if(UI.vfl==='out')l=l.filter(p=>!p.avail||p.stock===0);
 const subs=[...new Set(D().products.filter(p=>p.bid===b.id).map(p=>p.sub))];
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Products')}</h1><div class="row"><button class="btn g sm" data-act="csv">${ic('upload',16)} ${t('Bulk import')}</button><a class="btn p sm" href="#${RT('vprod')}-new">${ic('plus',16)} ${t('Add product')}</a></div></div>
 <div class="card pad stack"><div class="row between"><b>${t('Categories')}</b><span class="row" style="gap:0"><button class="btn t sm" data-act="subSuggest">${ic('plus',14)} ${t('Suggest a subcategory')}</button><button class="btn t sm" data-act="pillMgr">${ic('sliders',14)} ${t('Manage pills')}</button></span></div><div class="small muted">${t('Main categories are fixed by ApnaTown. You can suggest subcategories for admin approval.')}</div><div class="chips">${subs.map(s=>`<span class="chip">${esc(s)} <span class="cnt" style="background:var(--surface-2);color:var(--text)">${D().products.filter(p=>p.bid===b.id&&p.sub===s).length}</span></span>`).join('')}</div>${mySubs()}</div>
 <div class="row wrap-r"><div class="searchbar grow" style="min-width:200px">${ic('search',18)}<input data-in="vq" value="${esc(UI.vq||'')}" placeholder="${t('Search products or SKU')}" aria-label="${t('Search products')}"></div><select class="input" style="width:auto" data-chg="vfl">${[['','All'],['low','Low stock'],['out','Out of stock']].map(([k,l])=>`<option value="${k}" ${UI.vfl===k?'selected':''}>${t(l)}</option>`).join('')}</select></div>
 ${sel.length?`<div class="card pad row wrap-r" style="background:var(--primary-soft)"><b>${sel.length} ${t('selected')}</b><button class="btn g sm" data-act="bulk" data-v="in">${t('Mark in stock')}</button><button class="btn g sm" data-act="bulk" data-v="out">${t('Mark out of stock')}</button><button class="btn d sm" data-act="bulk" data-v="del">${t('Delete')}</button></div>`:''}
 <div id="vplist">${vplist(l)}</div></div>`};
const vplist=l=>tbl(['','Product','SKU','Price','Stock','Available',''],l.map(p=>[`<input type="checkbox" ${(UI.vsel||[]).includes(p.id)?'checked':''} data-chg="vsel" data-id="${p.id}" aria-label="${t('Select')} ${esc(nm(p.name))}" style="width:20px;height:20px;accent-color:var(--primary)">`,`<div class="row">${art(p.emoji,p.hue,'mini')}<div><b>${esc(nm(p.name))}</b><div class="xs muted">${esc(p.sub)} · ${esc(p.unit)}</div></div></div>`,p.sku,inr(p.price)+(p.mrp>p.price?`<span class="mrp">${inr(p.mrp)}</span>`:''),`<span class="badge ${p.stock===0?'bad':p.stock<=p.low?'warn':'ok'}">${p.stock}</span>`,`<span class="toggle"><input type="checkbox" ${p.avail?'checked':''} data-chg="vavail" data-id="${p.id}" aria-label="${t('Available')}"><span></span></span>`,`<a class="btn g sm" href="#${RT('vprod')}-${p.id}">${ic('edit',14)} ${t('Edit')}</a>`]));
INP.vq=v=>{UI.vq=v;const l=D().products.filter(p=>p.bid===ownerId()&&(!v||nm(p.name).toLowerCase().includes(v.toLowerCase())||p.sku.toLowerCase().includes(v.toLowerCase())));$('#vplist').innerHTML=vplist(l)};
CH.vfl=el=>{UI.vfl=el.value;render(true)};CH.vsel=el=>{const s=UI.vsel||[];UI.vsel=el.checked?[...s,el.dataset.id]:s.filter(x=>x!==el.dataset.id);render(true)};
CH.vavail=el=>{const p=prod(el.dataset.id);p.avail=el.checked;if(el.checked&&p.stock===0)p.stock=10;save();render(true);toast(el.checked?t('Marked available'):t('Marked unavailable'))};
A.bulk=el=>{const v=el.dataset.v,ids=UI.vsel||[];if(v==='del')return confirmBox(t('Delete selected products?'),t('This cannot be undone.'),t('Delete'),()=>{D().products=D().products.filter(p=>!ids.includes(p.id));D().cart;S.cart=S.cart.filter(c=>!ids.includes(c.pid));UI.vsel=[];save();render(true)},true);ids.forEach(id=>{const p=prod(id);p.avail=v==='in';if(v==='in'&&!p.stock)p.stock=10});UI.vsel=[];save();render(true);toast(t('Updated'))};
A.addSub=()=>sheet(`<h3>${t('Add category')}</h3><form data-form="addsub" class="stack" style="margin-top:10px">${field('Category name','n','',{req:1})}<button class="btn p">${t('Add')}</button></form>`);F.addsub=d=>{closeSheet();toast(t('Category added. Pick it when adding products.'),'check');UI.extraSubs=[...(UI.extraSubs||[]),d.n]};
A.csv=()=>sheet(`<h3>${t('Bulk import from CSV / Excel')}</h3><p class="small muted">${t('Paste rows: name, price, MRP, stock, unit. One product per line.')}</p><form data-form="csv" class="stack" style="margin-top:10px"><textarea class="input" name="rows" rows="6" aria-label="CSV rows">Moong Dal,140,155,30,1 kg\nSugar,46,50,80,1 kg</textarea><div class="drop small">${t('Or upload .csv / .xlsx')} <button type="button" class="btn g sm" data-act="fakeUpload">${t('Choose file')}</button></div><button class="btn p">${t('Import')}</button></form>`);
F.csv=d=>{let n=0;d.rows.split('\n').forEach(r=>{const c=r.split(',').map(x=>x.trim());if(c.length<4||!c[0]||isNaN(+c[1]))return;const hue=vb().hue;D().products.push({id:'p'+(D().products.length+100+n),bid:ownerId(),name:{en:c[0],hi:''},cat:vb().cat,price:+c[1],mrp:+c[2]||+c[1],unit:c[4]||'1 pc',emoji:catOf(vb().cat).e,hue,stock:+c[3]||0,low:5,variants:[],sku:ownerId().toUpperCase()+'-N'+(n+1),sub:'Imported',desc:c[0],specs:[],tags:[],featured:false,status:'active',avail:+c[3]>0});n++});save();closeSheet();render(true);toast(n+' '+t('products imported'),'upload')};
V.vprod=id=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const isNew=id==='new',p=isNew?{id:'',name:{en:'',hi:''},price:'',mrp:'',unit:'1 pc',sku:'',stock:10,low:5,variants:[],tags:[],sub:'Items',desc:'',avail:true,featured:false}:prod(id);if(!p||(!isNew&&p.bid!==ownerId()))return V.nf();
 const subs=[...new Set([...D().products.filter(x=>x.bid===ownerId()).map(x=>x.sub),...(UI.extraSubs||[])])];
 return `<div class="stack-lg"><a class="btn t sm" href="#${RT('vproducts')}" style="justify-self:start">${ic('cl',16)} ${t('Products')}</a><h1>${isNew?t('Add product'):t('Edit product')}</h1><form data-form="vprod" class="cols2"><input type="hidden" name="id" value="${p.id}"><div class="stack"><div class="card pad stack">${field('Product name (English)','en',p.name.en,{req:1})}${field('Product name (Hindi)','hi',p.name.hi)}${field('Description','desc',p.desc,{type:'textarea'})}${field('Category','sub',p.sub,{type:'select',opts:subs.map(s=>[s,s])})}</div><div class="card pad stack"><div class="grid g2">${field('Price (₹)','price',p.price,{req:1,type:'number',min:0,step:'0.01',im:'decimal'})}${field('MRP (₹)','mrp',p.mrp,{type:'number',min:0,step:'0.01'})}${field('Unit','unit',p.unit,{ph:'e.g. 1 kg'})}${field('SKU','sku',p.sku)}${field('Stock','stock',p.stock,{type:'number',min:0})}${field('Low-stock alert at','low',p.low,{type:'number',min:0})}</div>${field('Variants (comma separated)','variants',p.variants.join(', '),{ph:'5 kg, 10 kg'})}${field('Tags','tags',p.tags.join(', '),{ph:'fresh, local'})}</div></div>
 <div class="stack"><div class="card pad stack"><h3>${t('Photos')}</h3>${uploader('Add product photos (1:1)')}<div class="small muted">${t('Square photos look best. Max 5.')}</div></div><div class="card pad stack">${toggle('avail',p.avail,'Available for sale','tgform')}<input type="hidden" name="avail" value="${p.avail?1:0}" id="h_avail">${toggle('featured',p.featured,'Featured product','tgform')}<input type="hidden" name="featured" value="${p.featured?1:0}" id="h_featured"></div>
 ${!isNew?`<div class="card pad stack"><h3>${t('Shareable link')}</h3><div class="field"><input class="input" readonly value="${esc(shareUrl('prod-'+p.id))}" aria-label="Link"></div><div class="row"><button type="button" class="btn g grow" data-act="copy" data-v="${esc(shareUrl('prod-'+p.id))}">${ic('copy',16)} ${t('Copy')}</button><button type="button" class="btn s grow" data-act="share" data-id="${p.id}">${ic('share',16)} ${t('Share')}</button></div></div>`:''}<button class="btn p block">${t('Save product')}</button></div></form></div>`};
CH.tgform=el=>{const h=$('#h_'+el.dataset.k);if(h)h.value=el.checked?1:0};
F.vprod=d=>{const list=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const b=vb();let p=d.id?prod(d.id):null;const base={name:{en:d.en,hi:d.hi},desc:d.desc,sub:d.sub,price:+d.price,mrp:+d.mrp||+d.price,unit:d.unit,sku:d.sku||b.id.toUpperCase()+'-X',stock:+d.stock,low:+d.low,variants:list(d.variants),tags:list(d.tags),avail:d.avail==='1'&&+d.stock>0||d.avail==='1',featured:d.featured==='1'};
 if(p)Object.assign(p,base);else{p={id:'p'+(D().products.reduce((a,x)=>Math.max(a,+x.id.slice(1)),0)+1),bid:b.id,cat:b.cat,emoji:catOf(b.cat).e,hue:b.hue,specs:[['Pack size',base.unit]],status:'active',...base};D().products.push(p)}save();toast(t('Product saved'),'check');go(RT('vprod')+'-'+p.id)};
/* offers */
V.voffers=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const l=D().offers.filter(o=>o.bid===ownerId());const lc={pending:'Pending approval',active:'Active',paused:'Paused',ended:'Ended'};
 return `<div class="stack"><div class="row between"><h1>${t('Offers')}</h1><button class="btn p sm" data-act="offerEdit" data-id="">${ic('plus',16)} ${t('Create offer')}</button></div>${alertBox('info',t('New offers are reviewed by admin before they go live. Featured offers appear in the website’s offers section.'))}${tbl(['Offer','Type','Valid till','Status','Views','Uses','Featured',''],l.map(o=>[`<b>${esc(o.title)}</b>`,o.type==='percent'?o.value+'%':o.type==='flat'?'₹'+o.value:t('Free delivery'),fdate(o.to),`<span class="badge ${o.status==='active'?'ok':o.status==='pending'?'warn':o.status==='paused'?'info':'neu'}">${t(lc[o.status])}</span>`,o.views,o.uses,`<span class="toggle"><input type="checkbox" ${o.featured?'checked':''} data-chg="ofeat" data-id="${o.id}" aria-label="${t('Featured')}"><span></span></span>`,`<div class="row" style="gap:4px"><button class="btn g sm" data-act="offerEdit" data-id="${o.id}">${t('Edit')}</button>${o.status==='active'?`<button class="btn g sm" data-act="offerSt" data-id="${o.id}" data-v="paused">${t('Pause')}</button><button class="btn g sm" data-act="offerSt" data-id="${o.id}" data-v="ended">${t('End')}</button>`:o.status==='paused'?`<button class="btn p sm" data-act="offerSt" data-id="${o.id}" data-v="active">${t('Resume')}</button>`:''}</div>`]))}</div>`};
CH.ofeat=el=>{D().offers.find(o=>o.id===el.dataset.id).featured=el.checked;save();toast(t('Updated'))};
A.offerSt=el=>{D().offers.find(o=>o.id===el.dataset.id).status=el.dataset.v;save();render(true)};
A.offerEdit=el=>{const o=D().offers.find(x=>x.id===el.dataset.id)||{id:'',title:'',type:'percent',value:10,to:Date.now()+7*DAY,pids:[]};const ps=D().products.filter(p=>p.bid===ownerId());
 sheet(`<h3>${o.id?t('Edit offer'):t('Create offer')}</h3><form data-form="offer" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${o.id}">${field('Offer title','title',o.title,{req:1})}<div class="grid g2">${field('Discount type','type',o.type,{type:'select',opts:[['percent','Percent off'],['flat','Flat ₹ off'],['freedel','Free delivery']]})}${field('Value','value',o.value,{type:'number',min:0})}</div>${field('Valid till','to',new Date(o.to).toISOString().slice(0,10),{type:'date',req:1})}<div><div class="lbl small">${t('Applies to products (leave empty for whole shop)')}</div><div class="chips" style="flex-wrap:wrap">${ps.map(p=>`<label class="chip"><input type="checkbox" name="pid_${p.id}" ${o.pids.includes(p.id)?'checked':''} style="accent-color:var(--primary)"> ${esc(nm(p.name))}</label>`).join('')}</div></div>${uploader('Offer banner (16:9)')}<button class="btn p">${t('Submit for approval')}</button></form>`,{wide:true})};
F.offer=d=>{const pids=Object.keys(d).filter(k=>k.startsWith('pid_')).map(k=>k.slice(4));let o=D().offers.find(x=>x.id===d.id);const base={title:d.title,type:d.type,value:+d.value,to:new Date(d.to).getTime(),pids};if(o)Object.assign(o,base,{status:'pending'});else D().offers.unshift({id:rid('of'),bid:ownerId(),from:Date.now(),status:'pending',featured:false,views:0,uses:0,...base});notify('admin','Offer awaiting approval',nm(vb().name)+': '+d.title,'apromos','appr');save();closeSheet();render(true);toast(t('Sent to admin for approval'),'send')};
/* inventory */
V.vinv=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const l=D().products.filter(p=>p.bid===ownerId());return `<div class="stack"><div class="row between wrap-r"><h1>${t('Inventory')}</h1><button class="btn g sm" data-act="restock">${ic('layers',16)} ${t('Restock all low items to 20')}</button></div>${tbl(['Product','In stock','Low alert','Adjust','Availability'],l.map(p=>[`${p.emoji} ${esc(nm(p.name))}`,`<span class="badge ${p.stock===0?'bad':p.stock<=p.low?'warn':'ok'}">${p.stock}</span>`,p.low,`<div class="stepper"><button data-act="stk" data-id="${p.id}" data-d="-1" aria-label="${t('Decrease')}">−</button><b>${p.stock}</b><button data-act="stk" data-id="${p.id}" data-d="1" aria-label="${t('Increase')}">+</button></div>`,`<button class="btn ${p.avail?'g':'p'} sm" data-act="stkToggle" data-id="${p.id}">${p.avail?t('Mark out of stock'):t('Mark in stock')}</button>`]))}</div>`};
A.stk=el=>{const p=prod(el.dataset.id);p.stock=Math.max(0,p.stock+ +el.dataset.d);p.avail=p.stock>0;save();render(true)};A.stkToggle=el=>{const p=prod(el.dataset.id);p.avail=!p.avail;if(p.avail&&!p.stock)p.stock=10;save();render(true)};A.restock=()=>{D().products.filter(p=>p.bid===ownerId()&&p.stock<=p.low).forEach(p=>{p.stock=20;p.avail=true});save();render(true);toast(t('Restocked'),'check')};
/* reviews */
V.vreviews=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const f=UI.vrf||'all',l=D().reviews.filter(r=>r.tid===ownerId()&&(f==='all'||(f==='reply'?!r.reply&&r.status==='published':r.status==='reported'||r.reported)));
 return `<div class="stack"><h1>${t('Ratings & reviews')}</h1><div class="card pad">${ratingBreak(D().reviews.filter(r=>r.tid===ownerId()&&r.status==='published'))}</div><div class="chips">${[['all','All'],['reply','Needs reply'],['rep','Reported']].map(([k,lb])=>`<button class="chip ${f===k?'on':''}" data-act="vrf" data-v="${k}">${t(lb)}</button>`).join('')}</div>${l.length?l.map(r=>`<div class="stack" style="gap:6px">${revCard(r,'none')}<div class="row wrap-r"><button class="btn o sm" data-act="vreply" data-id="${r.id}">${r.reply?t('Edit reply'):t('Reply')}</button><button class="btn g sm" data-act="vreport" data-id="${r.id}">${ic('flag',14)} ${t('Report abusive')}</button>${r.status!=='published'?`<span class="badge warn">${t(r.status)}</span>`:''}</div></div>`).join(''):empty('⭐','No reviews here','Reviews from customers will show up here.')}</div>`};
A.vrf=el=>{UI.vrf=el.dataset.v;render(true)};
A.vreply=el=>{const r=D().reviews.find(x=>x.id===el.dataset.id);sheet(`<h3>${t('Reply to')} ${esc(r.name)}</h3><p class="small t2">${esc(r.text)}</p><form data-form="vreply" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${r.id}">${field('Your reply','reply',r.reply,{type:'textarea',req:1})}<button class="btn p">${t('Post reply')}</button></form>`)};
F.vreply=d=>{D().reviews.find(x=>x.id===d.id).reply=d.reply;save();closeSheet();render(true);toast(t('Reply posted'))};
A.vreport=el=>{const r=D().reviews.find(x=>x.id===el.dataset.id);r.reported=true;r.reports=(r.reports||0)+1;notify('admin','Review reported by vendor','Review by '+r.name,'areviews','review');save();render(true);toast(t('Reported to admin'),'flag')};
/* qr & links */
V.vqr=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const b=vb(),u=shareUrl('biz-'+b.id),tp=UI.qrTpl||'poster';
 return `<div class="stack-lg"><h1>${t('QR code & shareable links')}</h1><div class="cols2 eq"><div class="stack"><div class="chips">${[['poster','Poster (A4)'],['tent','Table tent'],['sticker','Sticker']].map(([k,l])=>`<button class="chip ${tp===k?'on':''}" data-act="qrtpl" data-v="${k}">${t(l)}</button>`).join('')}</div><div class="poster" style="${tp==='sticker'?'max-width:260px;border-radius:50%;aspect-ratio:1;align-content:center':tp==='tent'?'max-width:340px':''}"><div style="font-size:2rem">${b.emoji}</div><h2>${esc(nm(b.name))}</h2><div class="t2">${t('Scan to order from us')}</div>${qrSvg(u,b.emoji)}<div class="small"><b>Apna<span style="color:var(--primary)">Town</span>.in</b> · ${esc(areaName(b.area))}</div></div><div class="row noprint"><button class="btn p grow" onclick="window.print()">${ic('print',18)} ${t('Print poster')}</button><button class="btn g grow" data-act="copy" data-v="${esc(u)}">${ic('copy',18)} ${t('Copy link')}</button></div><div class="small muted noprint">${t('Tip: choose “Save as PDF” in the print window to download PNG/PDF copies.')}</div></div>
 <div class="stack noprint"><div class="card pad stack"><h3>${t('Business profile link')}</h3><input class="input" readonly value="${esc(u)}" aria-label="Link"><div class="row wrap-r"><a class="btn s sm" target="_blank" rel="noopener" href="${waH('','Visit '+nm(b.name)+' on ApnaTown: '+u).replace('/91','/')}">WhatsApp</a><button class="btn g sm" data-act="copy" data-v="${esc(u)}">Instagram</button><button class="btn g sm" data-act="copy" data-v="${esc(u)}">Facebook</button></div></div><div class="card pad stack"><h3>${t('Product links')}</h3>${D().products.filter(p=>p.bid===b.id).slice(0,6).map(p=>`<div class="row between"><span class="small truncate">${p.emoji} ${esc(nm(p.name))}</span><button class="btn g sm" data-act="copy" data-v="${esc(shareUrl('prod-'+p.id))}">${ic('copy',14)}</button></div>`).join('')}</div></div></div></div>`};
A.qrtpl=el=>{UI.qrTpl=el.dataset.v;render(true)};
/* media */
V.vmedia=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const b=vb();return `<div class="stack"><h1>${t('Gallery & media')}</h1><div class="card pad stack"><h3>${t('Photos')}</h3>${uploader('Add shop photos (4:3)')}<div class="grid g3">${b.gallery.map((g,i)=>`<div class="stack" style="gap:4px">${art(g,b.hue+i*20,'f')}<div class="row"><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="-1" aria-label="${t('Move left')}" ${i?'':'disabled'}>${ic('cl',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="1" aria-label="${t('Move right')}" ${i<b.gallery.length-1?'':'disabled'}>${ic('cr',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gdel" data-i="${i}" aria-label="${t('Delete')}">${ic('trash',16)}</button></div></div>`).join('')}</div></div>
 <div class="card pad stack"><h3>YouTube</h3><form data-form="yt" class="row">${`<input class="input" name="url" value="${esc(b.social.yt)}" placeholder="https://youtube.com/watch?v=..." aria-label="YouTube link">`}<button class="btn p">${t('Add')}</button></form>${b.social.yt?`<div class="card pad row"><div class="mini art" style="--h:0">▶️</div><span class="grow small truncate">${esc(b.social.yt)}</span></div>`:''}</div>
 <div class="card pad stack"><h3>Instagram</h3><form data-form="ig" class="row"><input class="input" name="ig" value="${esc(b.social.ig)}" placeholder="@yourshop" aria-label="Instagram handle"><button class="btn p">${t('Connect')}</button></form>${b.social.ig?`<div class="card pad row"><div class="mini art" style="--h:330">📷</div><div class="grow"><b>@${esc(b.social.ig)}</b><div class="small t2">${t('Preview: latest posts will show on your profile. If Instagram is slow we show a link instead.')}</div></div></div>`:''}</div></div>`};
A.gmove=el=>{const g=vb().gallery,i=+el.dataset.i,j=i+ +el.dataset.d;[g[i],g[j]]=[g[j],g[i]];save();render(true)};A.gdel=el=>{vb().gallery.splice(+el.dataset.i,1);save();render(true)};
F.yt=d=>{vb().social.yt=d.url;save();render(true);toast(t('Saved'))};F.ig=d=>{vb().social.ig=d.ig.replace('@','');save();render(true);toast(t('Connected'))};
